using System;using System.Collections.Generic;using System.IO;using Ashfall.Core;using Ashfall.Modules.Networking;using Ashfall.Modules.Sessions;
namespace Ashfall.Integration.Playable.Networking {
 public sealed class R24LanSupplyState {public readonly string Id,Family,Collector;public readonly int Amount;public readonly Float3 Position;public readonly long Revision;internal R24LanSupplyState(string id,string family,int amount,Float3 at,string collector,long revision){Id=id;Family=family;Amount=amount;Position=at;Collector=collector;Revision=revision;}}
 public sealed partial class R24LanLobby {
  const string SupplyFeature="playable.supply/1",SupplyCommand="playable.supply.collect/1";
  readonly Dictionary<string,R24LanSupplyState> sharedSupplies=new Dictionary<string,R24LanSupplyState>(StringComparer.Ordinal);long supplySequence;
  public R24LanSupplyState[] SharedSupplies{get{return CopySnapshot(sharedSupplies.Values);}}
  void ClearSharedSupplies(){sharedSupplies.Clear();foreach(var p in peers.Values)p.Supplies.Clear();}
  static bool SupplyFamily(string family){return family=="rifle"||family=="pistol"||family=="smg"||family=="shells"||family=="sniper"||family=="backpack"||family=="builds";}
  public bool RegisterSharedSupply(string id,string family,int amount,Float3 at){Check();if(State!=R24LanLobbyState.Hosting||SelectedMap==null||SelectedMap.Cancelled||!Wire.IsText(id,128,false)||!SupplyFamily(family)||amount<1||amount>10000||family=="backpack"&&amount!=1||!at.IsFinite||sharedSupplies.Count>=4096||sharedSupplies.ContainsKey(id))return false;PublishSupply(new R24LanSupplyState(id,family,amount,at,"",checked(++supplySequence)));return true;}
  public bool TryReadSharedSupply(string id,out R24LanSupplyState state){Check();state=null;return id!=null&&sharedSupplies.TryGetValue(id,out state);}
  public bool RequestSupply(string id,int hand){Check();if(!Wire.IsText(id,128,false)||hand<0||hand>1)return false;if(State==R24LanLobbyState.Hosting)return ApplySupply(OwnActor,id,hand);if(State!=R24LanLobbyState.Connected)return false;using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){Write(w,id,128);w.Write((byte)hand);return QueueGameCommand(SupplyCommand,m.ToArray());}}
  bool ApplySupply(string actor,string id,int hand){R24LanSupplyState item;CombatActor c;R24LanRawTrackingSample raw;var member=sessions.Get(actor);
   if(!InventoryLive||!LootAllowed(id)||hand<0||hand>1||member==null||member.Life!=SessionLife.Alive||!sharedSupplies.TryGetValue(id,out item)||item.Collector!=""||!combat.TryGetValue(actor,out c)||!Fresh(actor,clock.Now,out raw)||(raw.Pose.Flags&(hand==0?2:4))==0||Distance2(raw.Pose.Root.Position,item.Position)>20.25||Distance2(hand==0?raw.Pose.Left.Position:raw.Pose.Right.Position,item.Position)>4||rawWorldClear==null||!rawWorldClear(raw.Pose.Head.Position,item.Position))return false;
   if(item.Family=="backpack"){if(c.Capacity>=6)return false;c.Capacity++;}else if(item.Family=="builds"){if(c.Builds>Int32.MaxValue-item.Amount)return false;c.Builds+=item.Amount;}else{int reserve;c.Reserves.TryGetValue(item.Family,out reserve);if(reserve>Int32.MaxValue-item.Amount)return false;c.Reserves[item.Family]=reserve+item.Amount;}
   PublishSupply(new R24LanSupplyState(item.Id,item.Family,item.Amount,item.Position,actor,checked(++supplySequence)));return true;}
  byte[] SupplyFrame(R24LanSupplyState item){using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){Write(w,item.Id,128);Write(w,item.Family,16);w.Write(item.Amount);w.Write(item.Position.X);w.Write(item.Position.Y);w.Write(item.Position.Z);w.Write(item.Collector!="");if(item.Collector!="")Write(w,item.Collector,64);return Packet(PacketKind.Snapshot,SupplyFeature,OwnActor,m.ToArray(),item.Revision);}}
  void PublishSupply(R24LanSupplyState item){sharedSupplies[item.Id]=item;var frame=SupplyFrame(item);foreach(var p in peers.Values)if(p.Admitted)p.Supplies[item.Id]=frame;}
  void ReadSupply(Packet packet){try{using(var m=new MemoryStream(packet.Payload,false))using(var r=new BinaryReader(m,Utf8)){string id=Read(r,128),family=Read(r,16);int amount=r.ReadInt32();var at=new Float3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());string collector=r.ReadBoolean()?Read(r,64):"";R24LanSupplyState old;
   if(m.Position!=m.Length||packet.BaseSequence!=-1||packet.Sequence<1||amount<1||amount>10000||!SupplyFamily(family)||!at.IsFinite||sharedSupplies.Count>=4096&&!sharedSupplies.ContainsKey(id)||sharedSupplies.TryGetValue(id,out old)&&old.Revision>=packet.Sequence)return;sharedSupplies[id]=new R24LanSupplyState(id,family,amount,at,collector,packet.Sequence);}}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}}
  void ReadSupplyCommand(string actor,byte[] bytes){try{using(var m=new MemoryStream(bytes,false))using(var r=new BinaryReader(m,Utf8)){string id=Read(r,128);int hand=r.ReadByte();if(m.Position==m.Length)ApplySupply(actor,id,hand);}}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}}
  void FlushSupplies(string connection,Peer p){string sent=null;foreach(var entry in p.Supplies){if(!Send(connection,entry.Value))return;sent=entry.Key;break;}if(sent!=null)p.Supplies.Remove(sent);}
 }
}
